using System.Text.Json;
using Strata.Core.Content.Loading;

namespace Strata.Core.Content.Reference;

public sealed record ReferenceEntry(string Id, string Name, string Kind, string Category, string? Stage);

/// <summary>A coverage line: how much of one reference category the content implements.</summary>
public sealed record CoverageLine(string Category, int Total, int Covered, IReadOnlyList<ReferenceEntry> Missing)
{
    public double Percent => Total == 0 ? 100 : 100.0 * Covered / Total;
}

/// <summary>
/// The Terraria concept databases in data/reference (generated by tools/content/gen_reference.py) and coverage
/// computed from content <c>covers</c> links. Coverage is measured, never maintained by hand.
/// </summary>
public sealed class ReferenceCatalog
{
    public static readonly string[] Categories =
        { "items", "enemies", "bosses", "biomes", "recipes", "progression", "events", "npcs", "tiles", "buffs", "projectiles", "liquids" };

    private readonly Dictionary<string, List<ReferenceEntry>> _byCategory = new(StringComparer.Ordinal);
    private readonly HashSet<string> _ids = new(StringComparer.Ordinal);

    public IReadOnlyDictionary<string, List<ReferenceEntry>> ByCategory => _byCategory;

    public bool Contains(string id) => _ids.Contains(id);

    public static ReferenceCatalog Load(IDataSource data)
    {
        var catalog = new ReferenceCatalog();
        foreach (var category in Categories)
        {
            var path = $"data/reference/{category}.json";
            if (!data.Exists(path)) throw new FileNotFoundException($"Missing reference database {path}");
            using var doc = JsonDocument.Parse(data.ReadText(path));
            var list = new List<ReferenceEntry>();
            foreach (var e in doc.RootElement.GetProperty("entries").EnumerateArray())
            {
                var entry = new ReferenceEntry(e.GetProperty("id").GetString()!, e.GetProperty("name").GetString()!, e.GetProperty("kind").GetString()!,
                    category, e.TryGetProperty("stage", out var s) ? s.GetString() : null);
                list.Add(entry);
                catalog._ids.Add(entry.Id);
            }
            catalog._byCategory[category] = list;
        }
        return catalog;
    }

    /// <summary>All <c>covers</c> ids declared by content definitions, with the definition that declares them.</summary>
    public static Dictionary<string, List<string>> Covered(ContentDatabase content)
    {
        var map = new Dictionary<string, List<string>>(StringComparer.Ordinal);
        foreach (var registry in content.AllRegistries)
            foreach (var def in registry.Definitions)
                foreach (var id in def.Covers)
                {
                    if (!map.TryGetValue(id, out var list)) map[id] = list = new List<string>();
                    list.Add($"{registry.Category}:{def.Id}");
                }
        return map;
    }

    public List<CoverageLine> Coverage(ContentDatabase content)
    {
        var covered = Covered(content);
        return Categories.Select(c =>
        {
            var entries = _byCategory[c];
            var missing = entries.Where(e => !covered.ContainsKey(e.Id)).ToList();
            return new CoverageLine(c, entries.Count, entries.Count - missing.Count, missing);
        }).ToList();
    }
}
